    name = "ScienceLitExtract"
    icon = "FlaskConical"
    inputs = node_inputs(
        {"method": "regex", "patterns": {"strength": "(?P<value>\\d+(?:\\.\\d+)?)\\s*(?P<unit>MPa|GPa)"}}
    )
    outputs = node_outputs()

    def build_table(self) -> DataFrame:
        return output_table(self, "lit.extract")

    def build_report(self) -> Data:
